global using System.Diagnostics.CodeAnalysis;
using System.Diagnostics;
using Xtate.IoC;
foreach (var workers in new[] { 1, 4 })
{
    using var baseline = new BaselineWeakReferenceSet();
    using var current = new WeakReferenceSet();
    var instance = new object();
    Action oldCycle = () => { baseline.Add(instance); baseline.TryTake(out _); };
    Action newCycle = () => { current.Add(instance); current.TryTake(out _); };
    for (var i = 0; i < 20000; i++) { oldCycle(); newCycle(); }
    var oldTimes = new List<double>(); var newTimes = new List<double>();
    for (var run = 0; run < 7; run++)
    {
        if (run % 2 == 0) { oldTimes.Add(Measure(oldCycle, workers)); newTimes.Add(Measure(newCycle, workers)); }
        else { newTimes.Add(Measure(newCycle, workers)); oldTimes.Add(Measure(oldCycle, workers)); }
    }
    oldTimes.Sort(); newTimes.Sort();
    Console.WriteLine($"workers={workers}; baseline median={oldTimes[3]:F2}ms; synchronized median={newTimes[3]:F2}ms; ratio={newTimes[3]/oldTimes[3]:F2}");
    GC.KeepAlive(instance);
}
static double Measure(Action cycle, int workers)
{
    var timer = Stopwatch.StartNew();
    Parallel.For(0, workers, _ => { for (var i = 0; i < 200000 / workers; i++) cycle(); });
    return timer.Elapsed.TotalMilliseconds;
}
